Tool response:
Tool: create_follow_up_task
Description: Create Follow Up Task
Parameters:
    {
      "type": "object",
      "properties": {
        "customer_id": {
          "type": "integer",
          "title": "Customer Id"
        },
        "assigned_to_user_id": {
          "type": "integer",
          "title": "Assigned To User Id"
        },
        "subject": {
          "type": "string",
          "title": "Subject"
        },
        "description": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "title": "Description"
        },
        "task_type": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "title": "Task Type",
          "default": "call"
        },
        "due_date": {
          "type": "string",
          "title": "Due Date"
        },
        "due_time": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "title": "Due Time"
        },
        "priority": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "title": "Priority",
          "default": "normal"
        }
      },
      "required": [
        "customer_id",
        "assigned_to_user_id",
        "subject",
        "due_date"
      ]
    }

